{'name': 'POS Pine Labs', 'version': '1.0', 'category': 'Sales/Point of Sale', 'sequence': 6, 'summary': 'Integrate your POS with Pine Labs payment terminals', 'description': '\nAllow Pine Labs POS payments\n==============================\n\nThis module is available only for companies that use INR currency.\nIt enables customers to pay for their orders using debit/credit cards and UPI through Pine Labs POS terminals.\nA Pine Labs merchant account is required to process transactions.\nFeatures include:\n\n* Quick payments by swiping, scanning, or tapping your credit/debit card or UPI QR code at the payment terminal.\n* Supported cards: Visa, MasterCard, RuPay.\n    ', 'data': ['views/pos_payment_views.xml', 'views/pos_payment_method_views.xml'], 'depends': ['point_of_sale'], 'installable': True, 'assets': {'point_of_sale._assets_pos': ['pos_pine_labs/static/src/**/*'], 'web.assets_unit_tests': ['pos_pine_labs/static/tests/unit/data/**/*']}, 'author': 'UniSoft Systems Ltd.', 'license': 'LGPL-3'}